CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('student','teacher','admin');
CREATE TYPE exam_status AS ENUM ('draft','published','running','closed','archived');
CREATE TYPE submission_status AS ENUM ('queued','judging','completed','failed');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role user_role NOT NULL DEFAULT 'student', student_id varchar(64) UNIQUE, password_hash text, full_name varchar(120) NOT NULL, class_name varchar(120), github_id bigint UNIQUE, github_username varchar(120), github_avatar text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (student_id IS NOT NULL OR role <> 'student'));
CREATE TABLE exams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title varchar(255) NOT NULL, status exam_status NOT NULL DEFAULT 'draft', starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, ip_allowlist cidr[] NOT NULL DEFAULT '{}', require_manual_review boolean NOT NULL DEFAULT false, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK (ends_at > starts_at));
CREATE TABLE exam_participants (exam_id uuid NOT NULL REFERENCES exams(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES users(id), extra_minutes integer NOT NULL DEFAULT 0 CHECK (extra_minutes >= 0), ip_exempt boolean NOT NULL DEFAULT false, device_session_id uuid, PRIMARY KEY(exam_id,student_id));
CREATE TABLE questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_id uuid NOT NULL REFERENCES exams(id) ON DELETE CASCADE, ordinal integer NOT NULL, title text NOT NULL, statement text NOT NULL, time_limit_ms integer NOT NULL, memory_limit_kb integer NOT NULL, max_score numeric(8,2) NOT NULL, template_code text NOT NULL, student_start_marker text NOT NULL DEFAULT '// === STUDENT_CODE_START ===', student_end_marker text NOT NULL DEFAULT '// === STUDENT_CODE_END ===', UNIQUE(exam_id,ordinal));
CREATE TABLE test_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL REFERENCES questions(id) ON DELETE CASCADE, is_sample boolean NOT NULL DEFAULT false, input_data text NOT NULL, expected_output text NOT NULL, ordinal integer NOT NULL, UNIQUE(question_id,ordinal));
CREATE TABLE drafts (exam_id uuid NOT NULL, student_id uuid NOT NULL, question_id uuid NOT NULL REFERENCES questions(id), code text NOT NULL, version bigint NOT NULL CHECK(version>0), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(exam_id,student_id,question_id), FOREIGN KEY(exam_id,student_id) REFERENCES exam_participants(exam_id,student_id));
CREATE TABLE submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_id uuid NOT NULL, student_id uuid NOT NULL, status submission_status NOT NULL DEFAULT 'queued', submitted_at timestamptz NOT NULL DEFAULT now(), auto_submitted boolean NOT NULL DEFAULT false, snapshot_hash text NOT NULL, UNIQUE(exam_id,student_id), FOREIGN KEY(exam_id,student_id) REFERENCES exam_participants(exam_id,student_id));
CREATE TABLE submission_items (submission_id uuid NOT NULL REFERENCES submissions(id) ON DELETE RESTRICT, question_id uuid NOT NULL REFERENCES questions(id), source_code text NOT NULL, source_version bigint NOT NULL, PRIMARY KEY(submission_id,question_id));
CREATE TABLE judge_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES submissions(id), status varchar(32) NOT NULL DEFAULT 'queued', payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE judge_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES judge_tasks(id), question_id uuid NOT NULL REFERENCES questions(id), verdict varchar(32) NOT NULL, score numeric(8,2) NOT NULL DEFAULT 0, runtime_ms integer, memory_kb integer, detail jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(task_id,question_id));
CREATE TABLE exam_scores (exam_id uuid NOT NULL, student_id uuid NOT NULL, score numeric(8,2) NOT NULL DEFAULT 0, finalized_at timestamptz, PRIMARY KEY(exam_id,student_id), FOREIGN KEY(exam_id,student_id) REFERENCES exam_participants(exam_id,student_id));
CREATE TABLE score_audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_id uuid NOT NULL, student_id uuid NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), old_score numeric(8,2), new_score numeric(8,2) NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE screen_switch_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_id uuid NOT NULL, student_id uuid NOT NULL, switched_at timestamptz NOT NULL DEFAULT now(), duration_ms integer, metadata jsonb NOT NULL DEFAULT '{}');
CREATE INDEX drafts_updated_idx ON drafts(exam_id,student_id,updated_at); CREATE INDEX judge_tasks_status_idx ON judge_tasks(status,created_at);
